parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "invoice_no": {
      "type": "string",
      "description": "เลขที่ใบแจ้งหนี้ตามที่พิมพ์"
    },
    "invoice_date": {
      "type": "string",
      "description": "วันที่ตามที่พิมพ์ เช่น 15/10/2569"
    },
    "vendor_name": {
      "type": "string",
      "description": "ชื่อผู้ขาย (ผู้ออกใบแจ้งหนี้) ไม่ใช่ชื่อลูกค้า"
    },
    "vendor_tax_id": {
      "type": "string",
      "description": "เลขประจำตัวผู้เสียภาษี 13 หลักของผู้ขาย ไม่ใช่ของลูกค้า"
    },
    "lines": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "description": {
            "type": "string"
          },
          "qty": {
            "type": "number"
          },
          "unit_price": {
            "type": "number"
          },
          "amount": {
            "type": "number"
          }
        },
        "required": [
          "description",
          "qty",
          "unit_price",
          "amount"
        ]
      }
    },
    "subtotal": {
      "type": "number",
      "description": "ยอดรวมก่อนภาษีมูลค่าเพิ่มตามที่พิมพ์"
    },
    "vat": {
      "type": "number",
      "description": "ภาษีมูลค่าเพิ่มตามที่พิมพ์"
    },
    "total": {
      "type": "number",
      "description": "จำนวนเงินรวมทั้งสิ้นตามที่พิมพ์"
    }
  },
  "required": [
    "invoice_no",
    "invoice_date",
    "vendor_name",
    "vendor_tax_id",
    "lines",
    "subtotal",
    "vat",
    "total"
  ]
}
